PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z WHERE {
  ?z a brick:Zone ; rdfs:label ?zl .
  FILTER(?zl IN ("Core_bottom","Perimeter_mid_ZN_4","Perimeter_top_ZN_3")) .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z rdfs:label ?label .
  FILTER(str.contains(?label, "Perimeter_top_ZN_3") || str.contains(?label, "Core_bottom") || str.contains(?label, "Perimeter_mid_ZN_4")) .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
