import csv
day="2018-04-13"
targets={"134c4f67-a2ef-5cd4-b03a-f18a5601c587":"Core_bottom",
         "aae47278-33aa-5890-bc25-fe8f2730710b":"Perimeter_mid_ZN_4",
         "66009ccf-dd88-5be4-87fd-ed38ec990e48":"Perimeter_top_ZN_3"}
counts={t:0 for t in targets}
first={t:None for t in targets}
last={t:None for t in targets}
for row in csv.DictReader(open(VALUES_CSV)):
    tid=row["timeseries_id"]
    if tid in targets and row["timestamp"].startswith(day):
        counts[tid]+=1
        if first[tid] is None or row["timestamp"]<first[tid]: first[tid]=row["timestamp"]
        if last[tid] is None or row["timestamp"]>last[tid]: last[tid]=row["timestamp"]
for t,n in targets.items():
    print(n, counts[t], first[t], last[t])
